  Definition cm_st (pc : Z) (rax t0 t1 t2 : word) (out nc : Z) (a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m : mem) : machine_state :=
    MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (Z_to_bv 64 (b + 24)) (Z_to_bv 64 b)
            (Z_to_bv 64 (b + 48)) (Z_to_bv 64 out) (Z_to_bv 64 (b + 32)) a3 a4 a5 a6 a7
            (Z_to_bv 64 nc) (Z_to_bv 64 2147450880) (Z_to_bv 64 (Z.shiftr (b + 24) 3 + 2147450880)) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
       F (Z_to_bv 64 pc) fc None m (seg_rom bsegs).
