  (* [comment removed for export] *)
  Lemma cm_tail : forall (m1 : mem) (j0 : list byte) (back out sz prv op oe ic nc : Z) (jd : list byte)
      (rax t0 t1 t2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word),
    munch W m0 m1 -> wmono bsegs m0 m1 -> mem_inv bsegs m1 ->
    cm_frame m1 j0 back -> stk bsegs m1 lo (bv_unsigned sp + -64) ->
    rw_cells bsegs m1 (b + 24) [C8 (Z_to_bv 64 out); C8 (Z_to_bv 64 ic); C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 op); C8 (Z_to_bv 64 oe)] ->
    In (out, sz) (mb_put_es es insz n x) ->
    rw_cells bsegs m1 out [C8 (Z_to_bv 64 (b + 8)); C8 (Z_to_bv 64 prv)] ->
    rw_cells bsegs m1 (out + 16) [C8 (Z_to_bv 64 sz); CB (Z.to_nat (mb_block_size sz - 24)) jd] ->
    0 <= op -> nc = oe - op -> 1 <= nc -> ic + nc = insz + n -> 0 <= ic -> oe <= sz -> sz < 2^62 ->
    mb_out b (mb_put_es es insz n x) (insz + n) = (if oe =? sz then b + 8 else out) ->
    mb_outpos (mb_put_es es insz n x) (insz + n) = (if oe =? sz then 0 else oe) ->
    evt bsegs (commit_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc b es insz n x lo shi m0)
